const ORIGINAL_TEXT_MAP = new WeakMap<Node, string>();
const REVERSE_TO_EN = new Map<string, string>();
let reverseMapInitialized = false;
let cachedTranslations: Record<LanguageCode, Record<string, string>> | null = null;

function initReverseMap(externalTranslations?: Record<LanguageCode, Record<string, string>>) {
  if (externalTranslations) {
    cachedTranslations = externalTranslations;
  }
  if (reverseMapInitialized && !externalTranslations) return;
  reverseMapInitialized = true;

  // 1. Index all tool UI dictionary entries
  for (const lang of Object.keys(TOOL_UI_DICTIONARY) as LanguageCode[]) {
    if (lang === "en") continue;
    const dict = TOOL_UI_DICTIONARY[lang];
    if (!dict) continue;
    for (const [enKey, transVal] of Object.entries(dict)) {
      if (transVal && transVal.trim() && enKey && enKey.trim()) {
        REVERSE_TO_EN.set(transVal.trim(), enKey.trim());
      }
    }
  }

  // 2. Index all TRANSLATIONS entries (handles circular import gracefully)
  const transDict = cachedTranslations || (typeof TRANSLATIONS !== "undefined" ? TRANSLATIONS : null);
  if (transDict) {
    for (const lang of Object.keys(transDict) as LanguageCode[]) {
      if (lang === "en") continue;
      const dict = transDict[lang];
      const enDict = transDict.en;
      if (!dict || !enDict) continue;
      for (const [key, transVal] of Object.entries(dict)) {
        const enVal = enDict[key];
        if (transVal && transVal.trim() && enVal && enVal.trim()) {
          REVERSE_TO_EN.set(transVal.trim(), enVal.trim());
        }
      }
    }
  }

  if (typeof window !== "undefined") {
    (window as any).__REVERSE_TO_EN = REVERSE_TO_EN;
  }
}

let activeObserver: MutationObserver | null = null;
let isTranslating = false;
let currentActiveLang: LanguageCode = "en";

/**
 * Translates a single text node or element attribute based on the target language.
 */
function translateNode(node: Node, lang: LanguageCode) {
  initReverseMap();

  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.nodeValue;
    if (!text || !text.trim()) return;

    // Skip script, style, code, pre, contentEditable inputs
    const parent = node.parentElement;
    if (
      parent &&
      (parent.tagName === "SCRIPT" ||
        parent.tagName === "STYLE" ||
        parent.tagName === "CODE" ||
        parent.tagName === "PRE" ||
        parent.isContentEditable)
    ) {
      return;
    }

    const trimmed = text.trim();

    // Reverting or switching to English
    if (lang === "en") {
      // 1. Check if current text is an exact match for a translated foreign phrase
      const enFromReverse = REVERSE_TO_EN.get(trimmed);
      if (enFromReverse) {
        const leading = text.match(/^\s*/)?.[0] || "";
        const trailing = text.match(/\s*$/)?.[0] || "";
        const restored = leading + enFromReverse + trailing;
        if (node.nodeValue !== restored) {
          node.nodeValue = restored;
        }
        ORIGINAL_TEXT_MAP.set(node, restored);
        return;
      }

      // 2. Check dynamic action buttons with suffix: e.g. "画像圧縮を適用 (1 file)"
      const parenMatch = trimmed.match(/^([^(]+)(\s*\(.*\))$/);
      if (parenMatch) {
        const base = parenMatch[1].trim();
        const suffix = parenMatch[2];
        const enBase = REVERSE_TO_EN.get(base);
        if (enBase) {
          const leading = text.match(/^\s*/)?.[0] || "";
          const trailing = text.match(/\s*$/)?.[0] || "";
          const space = suffix.startsWith(" ") ? "" : " ";
          node.nodeValue = leading + enBase + space + suffix.trim() + trailing;
          ORIGINAL_TEXT_MAP.set(node, node.nodeValue);
          return;
        }
      }

      // 3. Check "Switch to <Tool>" prefixes in various languages
      const switchPrefixes = [
        { pre: "へ切り替え: ", enPre: "Switch to " },
        { pre: "切替：", enPre: "Switch to " },
        { pre: "Cambiar a ", enPre: "Switch to " },
        { pre: "Passer à ", enPre: "Switch to " },
        { pre: "Wechseln zu ", enPre: "Switch to " },
        { pre: "전환: ", enPre: "Switch to " },
        { pre: "切换至: ", enPre: "Switch to " },
        { pre: "स्विच करें: ", enPre: "Switch to " }
      ];
      for (const sp of switchPrefixes) {
        if (trimmed.startsWith(sp.pre)) {
          const rest = trimmed.slice(sp.pre.length).trim();
          const enRest = REVERSE_TO_EN.get(rest) || rest;
          node.nodeValue = sp.enPre + enRest;
          return;
        }
      }

      // 4. Check dynamic page indicators (e.g. "5 ページ中 1 ページ", "Página 1 de 5", etc.)
      const jaKoPage = trimmed.match(/^(\d+)\s*(?:ページ中|페이지\s*중)\s*(\d+)\s*(?:ページ|페이지)(.*)/);
      if (jaKoPage) {
        node.nodeValue = `Page ${jaKoPage[2]} of ${jaKoPage[1]}${jaKoPage[3] || ""}`;
        return;
      }
      const westernPage = trimmed.match(/^(?:Página|Page|Seite|第)\s*(\d+)\s*(?:de|sur|von|\/)\s*(\d+)(?:\s*页)?(.*)/i);
      if (westernPage) {
        node.nodeValue = `Page ${westernPage[1]} of ${westernPage[2]}${westernPage[3] || ""}`;
        return;
      }

      // 5. Check original text map
      const original = ORIGINAL_TEXT_MAP.get(node);
      if (original) {
        const origTrimmed = original.trim();
        let enOfOrig = REVERSE_TO_EN.get(origTrimmed);
        if (!enOfOrig) {
          const origParen = origTrimmed.match(/^([^(]+)(\s*\(.*\))$/);
          if (origParen) {
            const origEn = REVERSE_TO_EN.get(origParen[1].trim());
            if (origEn) {
              const space = origParen[2].startsWith(" ") ? "" : " ";
              enOfOrig = origEn + space + origParen[2].trim();
            }
          }
        }
        if (enOfOrig) {
          if (node.nodeValue !== enOfOrig) {
            node.nodeValue = enOfOrig;
          }
        } else {
          // Never overwrite current text with foreign text from original
          const hasForeign = /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF\uAC00-\uD7AF\u0900-\u097F]/.test(origTrimmed);
          if (!hasForeign && node.nodeValue !== original) {
            node.nodeValue = original;
          }
        }
      }
      return;
    }

    // Translating to a foreign language:
    // Determine the true English source text
    let original = ORIGINAL_TEXT_MAP.get(node);
    if (!original || REVERSE_TO_EN.has(original.trim())) {
      const enFromReverse = REVERSE_TO_EN.get(trimmed);
      if (enFromReverse) {
        const leading = text.match(/^\s*/)?.[0] || "";
        const trailing = text.match(/\s*$/)?.[0] || "";
        original = leading + enFromReverse + trailing;
      } else {
        const pMatch = trimmed.match(/^([^(]+)(\s*\(.*\))$/);
        if (pMatch) {
          const pEn = REVERSE_TO_EN.get(pMatch[1].trim());
          if (pEn) {
            const space = pMatch[2].startsWith(" ") ? "" : " ";
            original = pEn + space + pMatch[2].trim();
          } else {
            const hasForeign = /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF\uAC00-\uD7AF\u0900-\u097F]/.test(trimmed);
            original = hasForeign ? (ORIGINAL_TEXT_MAP.get(node) || text) : text;
          }
        } else {
          const hasForeign = /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF\uAC00-\uD7AF\u0900-\u097F]/.test(trimmed);
          original = hasForeign ? (ORIGINAL_TEXT_MAP.get(node) || text) : text;
        }
      }
      ORIGINAL_TEXT_MAP.set(node, original);
    }

    if (!original) original = text;

    const dict = TOOL_UI_DICTIONARY[lang];
    if (!dict) return;

    const sourceTrimmed = original.trim();

    // 1. Exact match in dictionary
    if (dict[sourceTrimmed]) {
      const leading = original.match(/^\s*/)?.[0] || "";
      const trailing = original.match(/\s*$/)?.[0] || "";
      const translated = leading + dict[sourceTrimmed] + trailing;
      if (node.nodeValue !== translated) {
        node.nodeValue = translated;
      }
      return;
    }

    // 2. Dynamic Action Buttons: e.g. "Apply Changes & Compress (1 file)", "Apply Changes & Resize (1200×800px)"
    if (trimmed.startsWith("Apply Changes & ")) {
      // Check if there is a parenthesis detail like " (1 file)" or " (1200×800px)"
      const parenMatch = trimmed.match(/^(Apply Changes & [^(]+)(\s*\(.*\))$/);
      if (parenMatch) {
        const base = parenMatch[1].trim();
        const suffix = parenMatch[2];
        const translatedBase = dict[base] || dict["Apply Changes"] || base;
        node.nodeValue = original.replace(trimmed, translatedBase + suffix);
        return;
      }
      // Or exact start match
      for (const key of Object.keys(dict)) {
        if (key.startsWith("Apply Changes & ") && trimmed.startsWith(key)) {
          const rest = trimmed.slice(key.length);
          node.nodeValue = original.replace(trimmed, dict[key] + rest);
          return;
        }
      }
    }

    // 3. Download / QR Code button with suffix e.g. "Download / QR Code (All as ZIP)"
    if (trimmed.startsWith("Download / QR Code")) {
      const baseKey = "Download / QR Code";
      const baseTrans = dict[baseKey] || baseKey;
      const rest = trimmed.slice(baseKey.length);
      node.nodeValue = original.replace(trimmed, baseTrans + rest);
      return;
    }

    // 4. "Switch to <Tool>" reciprocal button
    if (trimmed.startsWith("Switch to ")) {
      const rest = trimmed.replace("Switch to ", "");
      const translatedRest = dict[rest] || rest;
      const prefix =
        lang === "ja"
          ? "へ切り替え: "
          : lang === "hi"
          ? "स्विच करें: "
          : lang === "es"
          ? "Cambiar a "
          : lang === "fr"
          ? "Passer à "
          : lang === "de"
          ? "Wechseln zu "
          : lang === "ko"
          ? "전환: "
          : lang === "zh"
          ? "切换至: "
          : "Switch to ";
      node.nodeValue = prefix + translatedRest;
      return;
    }

    // 5. Indicators with prefixes: "Source:", "Cropped:", "Current Input:", "Compressed Output Size:"
    const colonPrefixes = [
      "Source:",
      "Cropped:",
      "Current Input:",
      "Compressed Output Size:",
      "Live Measured Output:",
      "Estimated Output:",
      "Supported:",
      "Max file size:",
      "Ratio:",
      "Original Size:",
      "Current File Size:",
      "Total Input Images:",
      "Quality Level:",
      "Original Total:",
      "Estimated Size:",
      "Estimated Savings:",
      "Color:",
      "Size:",
      "Font:",
      "Background:",
      "Thickness:",
      "Marker Color:",
      "Redaction Type:",
      "Preset:",
      "File Name:",
      "File Size:",
      "Rotated Pages:",
      "Stroke:",
      "Source Size:",
      "Page Size:",
      "Margins:",
      "Source File:",
      "Targets:",
      "Target Image Dimensions:",
      "Format & Resolution:",
      "File Format:",
      "Architecture:",
      "Privacy / Server:",
      "Scale:",
      "Zoom:",
      "Width:",
      "Height:",
      "DPI:",
      "Total Pages:",
      "Total:",
      "Selected:",
      "Current:",
      "Original:",
      "Compressed:",
      "Margin:",
      "Spacing:",
      "Angle:",
      "Rotation:",
      "Position:",
      "Opacity:",
      "Font Size:",
      "Password:",
      "Confirm Password:",
      "Status:",
      "Progress:",
      "Resolution:",
      "Dimensions:",
      "Aspect Ratio:",
      "Format:",
      "Page:",
      "Pages:",
      "Mode:"
    ];
    for (const cp of colonPrefixes) {
      if (trimmed.startsWith(cp)) {
        const translatedPrefix = dict[cp] || cp;
        const rest = trimmed.slice(cp.length);
        node.nodeValue = original.replace(trimmed, translatedPrefix + rest);
        return;
      }
    }

    // 6. Selected file count: "Selected (X files)"
    if (trimmed.startsWith("Selected (")) {
      const selTrans = dict["Selected"] || "Selected";
      const rest = trimmed.replace("Selected", selTrans);
      node.nodeValue = original.replace(trimmed, rest);
      return;
    }

    // 7. Page indicators: "Page X of Y"
    if (/^Page\s+\d+\s+of\s+\d+/i.test(trimmed)) {
      const parts = trimmed.match(/^Page\s+(\d+)\s+of\s+(\d+)(.*)/i);
      if (parts) {
        const cur = parts[1];
        const tot = parts[2];
        const extra = parts[3] || "";
        const formatted =
          lang === "ja"
            ? `${tot} ページ中 ${cur} ページ${extra}`
            : lang === "ko"
            ? `${tot}페이지 중 ${cur}페이지${extra}`
            : lang === "zh"
            ? `第 ${cur} / ${tot} 页${extra}`
            : lang === "hi"
            ? `पृष्ठ ${cur} / ${tot}${extra}`
            : lang === "es"
            ? `Página ${cur} de ${tot}${extra}`
            : lang === "fr"
            ? `Page ${cur} sur ${tot}${extra}`
            : lang === "de"
            ? `Seite ${cur} von ${tot}${extra}`
            : trimmed;
        node.nodeValue = original.replace(trimmed, formatted);
        return;
      }
    }
  } else if (node.nodeType === Node.ELEMENT_NODE) {
    const el = node as HTMLElement;
    const dict = TOOL_UI_DICTIONARY[lang];
    if (!dict && lang !== "en") return;

    // Handle input & textarea placeholders
    if (el.hasAttribute("placeholder")) {
      const orig = el.getAttribute("data-orig-ph") || el.getAttribute("placeholder") || "";
      if (!el.hasAttribute("data-orig-ph")) {
        el.setAttribute("data-orig-ph", orig);
      }
      const enKey = REVERSE_TO_EN.get(orig.trim()) || orig.trim();
      if (lang === "en") {
        el.setAttribute("placeholder", enKey);
      } else if (dict && dict[enKey]) {
        el.setAttribute("placeholder", dict[enKey]);
      }
    }

    // Handle element titles & tooltips
    if (el.hasAttribute("title") && el.getAttribute("title")) {
      const orig = el.getAttribute("data-orig-title") || el.getAttribute("title") || "";
      if (!el.hasAttribute("data-orig-title")) {
        el.setAttribute("data-orig-title", orig);
      }
      const enKey = REVERSE_TO_EN.get(orig.trim()) || orig.trim();
      if (lang === "en") {
        el.setAttribute("title", enKey);
      } else if (dict && dict[enKey]) {
        el.setAttribute("title", dict[enKey]);
      }
    }

    // Handle aria-labels
    if (el.hasAttribute("aria-label") && el.getAttribute("aria-label")) {
      const orig = el.getAttribute("data-orig-aria") || el.getAttribute("aria-label") || "";
      if (!el.hasAttribute("data-orig-aria")) {
        el.setAttribute("data-orig-aria", orig);
      }
      const enKey = REVERSE_TO_EN.get(orig.trim()) || orig.trim();
      if (lang === "en") {
        el.setAttribute("aria-label", enKey);
      } else if (dict && dict[enKey]) {
        el.setAttribute("aria-label", dict[enKey]);
      }
    }
  }
}

/**
 * Traverses an element tree and applies native translations.
 */
function walkTree(root: Node, lang: LanguageCode) {
  if (!root) return;

  // Skip non-translatable container trees
  if (root.nodeType === Node.ELEMENT_NODE) {
    const tag = (root as Element).tagName;
    if (tag === "SCRIPT" || tag === "STYLE" || tag === "NOSCRIPT" || tag === "SVG" || tag === "CANVAS") {
      return;
    }
  }

  const walker = document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT,
    {
      acceptNode(node) {
        if (node.nodeType === Node.ELEMENT_NODE) {
          const tag = (node as Element).tagName;
          if (tag === "SCRIPT" || tag === "STYLE" || tag === "NOSCRIPT" || tag === "SVG" || tag === "CANVAS") {
            return NodeFilter.FILTER_REJECT;
          }
        }
        return NodeFilter.FILTER_ACCEPT;
      }
    }
  );

  let current: Node | null = walker.currentNode;
  while (current) {
    translateNode(current, lang);
    current = walker.nextNode();
  }
}

let hasTranslated = false;
let translateDebounceTimer: any = null;

/**
 * Applies native in-browser translations to the Studio Canvas,
 * tool components, panels, staging shelf, and open modals.
 * Works 100% locally and offline without external services or Google Translate.
 */
export function applyStudioNativeTranslation(
  lang: LanguageCode,
  externalTranslations?: Record<LanguageCode, Record<string, string>>
) {
  if (typeof document === "undefined") return;
  currentActiveLang = lang;
  if (externalTranslations) {
    cachedTranslations = externalTranslations;
    initReverseMap(externalTranslations);
  }

  hasTranslated = true;

  if (translateDebounceTimer) {
    clearTimeout(translateDebounceTimer);
  }

  translateDebounceTimer = setTimeout(() => {
    if (isTranslating) return;
    isTranslating = true;
    try {
      const root = document.getElementById("root") || document.body;
      if (root) {
        walkTree(root, lang);
      }
    } finally {
      isTranslating = false;
    }

    initStudioMutationObserver();
  }, 10);
}

/**
 * Initializes a DOM MutationObserver to reactively translate newly mounted
 * tools or dialogs in real time without causing infinite mutation loops.
 */
export function initStudioMutationObserver() {
  if (typeof document === "undefined" || activeObserver) return;

  const target = document.getElementById("root") || document.body;
  if (!target) return;

  activeObserver = new MutationObserver((mutations) => {
    if (isTranslating || currentActiveLang === "en") return;

    isTranslating = true;
    try {
      for (const m of mutations) {
        if (m.type === "childList") {
          m.addedNodes.forEach((node) => {
            if (node.nodeType === Node.ELEMENT_NODE) {
              walkTree(node, currentActiveLang);
            }
          });
        }
      }
    } finally {
      isTranslating = false;
    }
  });

  // Strictly observe only newly added DOM nodes (childList).
  // NEVER observe characterData or attributes to avoid browser-freezing loops!
  activeObserver.observe(target, {
    childList: true,
    subtree: true
  });
}
